/* board_data.h - the 250407 board as plain tables (generated by
 * tools/kicad2c.py into board_data.c). Coordinates are in millimeters,
 * x to the right, y down, as in KiCad. */
#ifndef BOARD_DATA_H
#define BOARD_DATA_H

typedef struct {
    const char *name;       /* pad name: "1".."40" for ICs, letters on some connectors */
    float x, y;             /* absolute center position (mm) */
    float w, h;             /* pad size (mm) */
    int net;                /* index into bd_nets[], or -1 if unconnected */
} bd_pad_t;

typedef struct {
    const char *ref;        /* "U17" */
    const char *value;      /* "PLA_U17", "3K3", ... */
    const char *footprint;  /* KiCad footprint name */
    int first_pad, npads;   /* range in bd_pads[] */
} bd_comp_t;

extern const float bd_outline[4];   /* x0, y0, x1, y1 of the board edge */
extern const char *const bd_nets[];
extern const int bd_nnets;
extern const bd_pad_t bd_pads[];
extern const int bd_npads;
extern const bd_comp_t bd_comps[];
extern const int bd_ncomps;

#endif
